    let home = '/home/smartev';
    if (typeof process !== 'undefined' && process.env) {
        home = process.env.HOME || process.env.USERPROFILE || home;
    }
    const dataDir = home + '/.node-red';
    try {
        if (!fs.existsSync(dataDir)) {
            fs.mkdirSync(dataDir, { recursive: true });
        }
    } catch(e) {}
    return dataDir;
}

    const DATA_DIR = resolveDataDir();
    const STATES_FILE = path.join(DATA_DIR, 'last-ui-states.json');

    if (fs.existsSync(STATES_FILE)) {
        const raw = fs.readFileSync(STATES_FILE, 'utf8');
        if (raw && raw.trim()) {
            let states = JSON.parse(raw) || {};
            flow.set('last_ui_states', states);
            for (let k in states) {
                if (states[k] && states[k].amp) {
                    flow.set('last_user_set_amp_' + k, Number(states[k].amp));
                    flow.set('last_user_set_amp_' + k.toLowerCase(), Number(states[k].amp));
                }
            }

            let validUserNames = [];
            try {
                const SMART_FILE = path.join(DATA_DIR, 'smart-parking-config.json');
                if (fs.existsSync(SMART_FILE)) {
                    const cfg = JSON.parse(fs.readFileSync(SMART_FILE, 'utf8'));
                    if (cfg && cfg.USERS) {
                        validUserNames = Object.values(cfg.USERS).map(u => u.name);
                    }
                }
            } catch(e) {}

            // Filter states by currently configured chargers
            if (validUserNames.length > 0 || true) {
                let validChargerIds = [];
                try {
                    const SMART_FILE = path.join(DATA_DIR, 'smart-parking-config.json');
                    if (fs.existsSync(SMART_FILE)) {
                        const cfg = JSON.parse(fs.readFileSync(SMART_FILE, 'utf8'));
                        if (cfg && cfg.CHARGERS) {
                            validChargerIds = Object.keys(cfg.CHARGERS);
                        }
                    }
                } catch(e) {}

                if (validChargerIds.length > 0) {
                    const filteredStates = {};
                    for (let cid in states) {
                        if (validChargerIds.includes(cid) || validChargerIds.some(v => v.toLowerCase() === cid.toLowerCase() || v.split('_')[0] === cid.split('_')[0])) {
                            filteredStates[cid] = states[cid];
                        }
