return msg;

const cid = msg.chargerId || 'solax_1';
let type = msg.chargerType;
if (!type && cid) {
    let cLow = cid.toLowerCase();
    if (cLow.includes('easee')) type = 'easee';
    else if (cLow.includes('victron')) type = 'victron';
    else if (cLow.includes('solax')) type = 'solax';
    else if (cLow.includes('goe') || cLow.includes('go-e')) type = 'goe';
}

const amp = Number(msg.payload ? msg.payload.amp : 0);
if (!amp || isNaN(amp) || amp < 6 || amp > 32) return null;

const now = Date.now();
flow.set('last_write_time_' + cid, now);
flow.set('last_write_amp_' + cid, amp);
flow.set('last_user_set_amp_' + cid, amp);
flow.set('last_user_set_amp_' + cid.toLowerCase(), amp);

let states = flow.get('last_ui_states') || {};
if (states[cid]) {
    states[cid].amp = amp;
    states[cid].targetAmp = amp;
    states[cid].desiredAmp = amp;
    states[cid].userSetAmp = amp;
    flow.set('last_ui_states', states);
}

node.warn('⚡ Route Amperage: Fast Direct Setting ' + amp + 'A for charger: ' + cid + ' (type: ' + type + ')');
node.status({ fill: 'blue', shape: 'dot', text: 'Set ' + amp + 'A on ' + cid });

const smartConf = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { CHARGERS: {} };
const _net = (typeof net !== 'undefined' && net) ? net : global.get('net');

if (type === 'victron') {
    let victronIp = '192.168.20.176';
    if (smartConf.CHARGERS && smartConf.CHARGERS[cid] && smartConf.CHARGERS[cid].ip) {
        victronIp = smartConf.CHARGERS[cid].ip.trim();
    }
    // Direct ultra-fast native TCP socket write to Victron register 5016 (FC 0x06)
    try {
        if (_net) {
            const client = new _net.Socket();
            client.setTimeout(1200);
            const buf = Buffer.alloc(12);
            buf.writeUInt16BE(1, 0);
            buf.writeUInt16BE(0, 2);
            buf.writeUInt16BE(6, 4);
            buf.writeUInt8(1, 6);
            buf.writeUInt8(6, 7);
            buf.writeUInt16BE(5016, 8);
            buf.writeUInt16BE(amp, 10);
            client.connect(502, victronIp, function() { client.write(buf); });
            client.on('data', function() { client.destroy(); node.status({ fill: 'green', shape: 'dot', text: 'Victron ' + amp + 'A (ACK)' }); });
            client.on('error', function(e) { client.destroy(); node.error('Victron socket err: ' + e.message); });
            client.on('timeout', function() { client.destroy(); node.warn('Victron socket timeout'); });
        }
    } catch(e) { node.error('Victron write failed: ' + e.message); }
