            const buf = Buffer.alloc(12);
            buf.writeUInt16BE(1, 0);
            buf.writeUInt16BE(0, 2);
            buf.writeUInt16BE(6, 4);
            buf.writeUInt8(1, 6);
            buf.writeUInt8(6, 7);
            buf.writeUInt16BE(299, 8);
            buf.writeUInt16BE(amp, 10);
            client.connect(502, goeIp, function() { client.write(buf); });
            client.on('data', function() { client.destroy(); node.status({ fill: 'green', shape: 'dot', text: 'Go-E ' + amp + 'A (ACK)' }); });
            client.on('error', function(e) { client.destroy(); node.error('Go-E socket err: ' + e.message); });
            client.on('timeout', function() { client.destroy(); node.warn('Go-E socket timeout'); });
        }
    } catch(e) { node.error('Go-E write failed: ' + e.message); }
    return [null, null, null, null];
} else if (type === 'solax') {
    let solaxIp = '192.168.20.236';
    if (smartConf.CHARGERS && smartConf.CHARGERS[cid] && smartConf.CHARGERS[cid].ip) {
        solaxIp = smartConf.CHARGERS[cid].ip.trim();
    }

    flow.set('solax_last_amp_write_ts_' + cid, now);
    flow.set('solax_last_amp_write_val_' + cid, amp);

    const amp100 = Math.round(amp * 100);
    const amp1000 = Math.round(amp * 1000);

    // Direct native Node.js socket (FC 0x06 Write Single Register)
    try {
        if (_net) {
            const regs = [
                [1556, 32],
                [1576, amp100],
                [1572, amp100],
                [1615, amp100],
                [1563, amp1000],
                [1598, 1]
            ];
            let idx = 0;
            function sendNextReg() {
                if (idx >= regs.length) return;
                const pair = regs[idx++];
                const client = new _net.Socket();
                client.setTimeout(1200);
                const buf = Buffer.alloc(12);
                buf.writeUInt16BE(1, 0);
                buf.writeUInt16BE(0, 2);
                buf.writeUInt16BE(6, 4);
                buf.writeUInt8(1, 6);
                buf.writeUInt8(6, 7);
                buf.writeUInt16BE(pair[0], 8);
                buf.writeUInt16BE(pair[1], 10);
                client.connect(502, solaxIp, function() { client.write(buf); });
                client.on('data', function() { client.destroy(); setTimeout(sendNextReg, 120); });
                client.on('error', function() { client.destroy(); setTimeout(sendNextReg, 120); });
                client.on('timeout', function() { client.destroy(); setTimeout(sendNextReg, 120); });
            }
            sendNextReg();
        }
    } catch(e) {}
    return [null, null, null, null];
} else if (type === 'easee') {
