const smartConfig = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { CHARGERS: {} };

let total_kw = 0;
let active = [];
const nowTs = Date.now();

for (let cid in states) {
    let s = states[cid];
    if (s.occupied && s.isCharging && !s.isOffline) {
        let kw = s.power || 0;
        total_kw += kw;

        let confCharger = (smartConfig.CHARGERS && smartConfig.CHARGERS[cid]) ? smartConfig.CHARGERS[cid] : {};
        const type = confCharger.type || (cid.includes('victron') ? 'victron' : (cid.includes('easee') ? 'easee' : (cid.includes('solax') ? 'solax' : 'goe')));

        const defaultMinAmp = (type === 'victron') ? 6 : 6;
        const defaultMaxAmp = (type === 'victron') ? 20 : 32;

        const minAmp = (confCharger.minAmp !== undefined && confCharger.minAmp !== null) ? Number(confCharger.minAmp) : defaultMinAmp;
        const maxAmp = (confCharger.maxAmp !== undefined && confCharger.maxAmp !== null) ? Number(confCharger.maxAmp)
                      : ((confCharger.amp !== undefined && confCharger.amp !== null) ? Number(confCharger.amp) : defaultMaxAmp);

        let userSet = flow.get('last_user_set_amp_' + cid) || s.userSetAmp || s.desiredAmp || s.targetAmp || s.amp;
        let desired = (userSet !== undefined && userSet !== null) ? Number(userSet) : minAmp;
        if (desired > maxAmp) desired = maxAmp;
        if (desired < minAmp) desired = minAmp;

        let current = (s.amp !== undefined && s.amp !== null) ? Number(s.amp) : desired;
        if (current > maxAmp) current = maxAmp;
        if (current < minAmp) current = minAmp;

        let lastWriteTime = flow.get('last_write_time_' + cid) || 0;
        let isUserOverride = (nowTs - lastWriteTime < 60000); // 60-second grace period for manual UI changes

        let kwPerAmp = (type === 'victron') ? 0.69 : 0.23;
        if (s.power > 0.5 && s.amp >= 6) {
            let actualRatio = s.power / s.amp;
            let detectedPhases = (actualRatio > 0.45) ? 3 : 1;
            flow.set('detected_phases_' + cid, detectedPhases);
        }
        let cachedPhases = flow.get('detected_phases_' + cid);
        if (cachedPhases !== undefined) {
            kwPerAmp = cachedPhases * 0.23;
        }

        active.push({
            id: cid,
            state: s,
            type: type,
            currentAmp: current,
            desiredAmp: desired,
            minAmp: minAmp,
            maxAmp: maxAmp,
            kwPerAmp: kwPerAmp,
            isUserOverride: isUserOverride
        });
    }
}

