let max_grid_curr = 0;

if (lastShelly && lastShelly.status && lastShelly.online) {
    let status = lastShelly.status;
    let ga = Number(status.a_current) || 0;
    let gb = Number(status.b_current) || 0;
    let gc = Number(status.c_current) || 0;
    max_grid_curr = Math.max(ga, gb, gc);

    let pa = Number(status.a_act_power) || 0;
    let pb = Number(status.b_act_power) || 0;
    let pc = Number(status.c_act_power) || 0;
    let rawTotalW = Number(status.total_act_power);
    if (!isNaN(rawTotalW) && rawTotalW > 0) {
        grid_total_kw = rawTotalW / 1000.0;
    } else {
        grid_total_kw = (pa + pb + pc) / 1000.0;
    }
    if (grid_total_kw > 0) useShelly = true;
}

