// Only overload if grid_total_kw > TOTAL_POWER OR (max_grid_curr > CURRENT_LIMIT_PER_PHASE + 3.0 && grid_total_kw > TARGET_LIMIT)
let isOverloaded = useShelly 
    ? (grid_total_kw > TOTAL_POWER || (max_grid_curr > CURRENT_LIMIT_PER_PHASE + 5.0 && grid_total_kw > TARGET_LIMIT))
    : (total_kw > TARGET_LIMIT);

if (isOverloaded) {
    let effectiveLimit = useShelly ? TOTAL_POWER : TARGET_LIMIT;
    let currentTotal = useShelly ? grid_total_kw : total_kw;
    let overload_kw = currentTotal - effectiveLimit;

    node.warn('⚠️ DLB OVERLOAD DETECTED: ' + currentTotal.toFixed(2) + 'kW > ' + effectiveLimit + 'kW. Reducing chargers...');

    for (let el of active) {
        // Do not force reduction below minAmp
        if (el.currentAmp > el.minAmp) {
            let reduction = Math.max(1, Math.ceil(overload_kw / (el.kwPerAmp * active.length)));
            let new_amp = el.currentAmp - reduction;
            if (new_amp < el.minAmp) new_amp = el.minAmp;

            if (new_amp < el.currentAmp) {
                el.state.amp = new_amp;
                stateChanged = true;
                node.warn('⚡ DLB CUT: ' + el.id + ' ' + el.currentAmp + 'A → ' + new_amp + 'A');
                msgs.push({
                    chargerId: el.id,
                    chargerType: el.type,
                    payload: { amp: new_amp }
                });
            }
        }
    }
} else {
    // Normal / Headroom available: Raise towards desiredAmp if charger is below what user wanted
    let currentTotal = useShelly ? grid_total_kw : total_kw;
    let headroom = TARGET_LIMIT - currentTotal;

    if (headroom >= 1.0) {
        let upgradable = active.filter(el => el.currentAmp < el.desiredAmp);
        for (let el of upgradable) {
            if (headroom < 0.5) break;
            let new_amp = el.desiredAmp; // Snap immediately to user desired setting if headroom allows
            if (new_amp > el.maxAmp) new_amp = el.maxAmp;

            if (new_amp > el.currentAmp) {
                el.state.amp = new_amp;
                stateChanged = true;
                node.warn('⚡ DLB RESTORE: ' + el.id + ' ' + el.currentAmp + 'A → ' + new_amp + 'A (headroom=' + headroom.toFixed(1) + 'kW)');
                msgs.push({
                    chargerId: el.id,
                    chargerType: el.type,
                    payload: { amp: new_amp }
                });
                headroom -= (new_amp - el.currentAmp) * el.kwPerAmp;
            }
        }
    }
}

