    totalE = Number(((arr[14] !== undefined && Number(arr[14]) > 0) ? arr[14] : (arr[9] || 0)) / 10.0);
}

let maxCurrent = Math.max(i1, i2, i3);
let isCharging = (rawStatus === 2) || (pW > 100);
let plugged = (rawStatus >= 1 && rawStatus <= 8) || isCharging || (maxCurrent > 0.3) || (pW > 20);
if (!isCharging) {
    pW = 0;
    pKW = 0;
}
let isCharged = (rawStatus === 3 && !isCharging && singleE > 0.1);

// User Amperage priority
let lastWriteTs = flow.get('solax_last_amp_write_ts_' + cid) || 0;
let lastWriteVal = flow.get('solax_last_amp_write_val_' + cid) || 0;
let isRecentWrite = (Date.now() - lastWriteTs < 15000) && (lastWriteVal >= 6 && lastWriteVal <= 32);

let userAmp = flow.get('last_user_set_amp_' + cid) || flow.get('last_user_set_amp_' + cid.toLowerCase());
let currentAmpVal = 16;

if (isRecentWrite) {
    currentAmpVal = lastWriteVal;
} else if (userAmp && userAmp >= 6 && userAmp <= 32) {
    currentAmpVal = userAmp;
} else if (isCharging && maxCurrent >= 5.0) {
    currentAmpVal = Math.round(maxCurrent);
} else if (msg.amp && msg.amp >= 6 && msg.amp <= 32) {
    currentAmpVal = msg.amp;
} else if (chConf && chConf.amp) {
    currentAmpVal = Number(chConf.amp);
}

let carsConfig = global.get('carsConfig', 'default') || {};
let cConf = carsConfig[chConf.zone + '-' + chConf.spot] || {};
let color = cConf.color || '#00d68f';

let statusCode = isCharging ? 2 : (plugged ? 1 : 0);
let statusLabel = isCharging ? 'Charging' : (plugged ? 'Connected' : 'Available');
let name = cConf.name || (plugged ? (currentUser || statusLabel) : '');

flow.set('solax_status_' + cid, statusCode);
flow.set('solax_status_' + cid.toLowerCase(), statusCode);

let resObj = {
    chargerId: cid,
    occupied: plugged,
    isPluggedIn: plugged,
    isCharging: isCharging,
    isCharged: isCharged,
    vehicleStateText: isCharging ? '⚡ Vehicle Charging (Active Charging)' : (plugged ? '🟡 Vehicle Connected (Standby)' : '🟢 Vehicle Disconnected (Available)'),
    status_code: statusCode,
    raw_status: rawStatus,
    status_label: statusLabel,
    power: pKW,
    powerKW: pKW,
    powerW: pW,
    energy: Number(totalE.toFixed(2)),
    totalEnergy: Number(totalE.toFixed(2)),
    totalEnergyKWh: Number(totalE.toFixed(2)),
    sessionEnergy: Number(singleE.toFixed(2)),
    singleChargeEnergy: Number(singleE.toFixed(2)),

    voltage: Number(v1.toFixed(2)),
    voltage1: Number(v1.toFixed(2)),
    voltage2: Number(v2.toFixed(2)),
    voltage3: Number(v3.toFixed(2)),
    voltageL1: v1.toFixed(2) + ' V',
    voltageL2: v2.toFixed(2) + ' V',
    voltageL3: v3.toFixed(2) + ' V',
    current1: Number(i1.toFixed(2)),
    current2: Number(i2.toFixed(2)),
    current3: Number(i3.toFixed(2)),
    currentL1: i1.toFixed(2) + ' A',
    currentL2: i2.toFixed(2) + ' A',
    currentL3: i3.toFixed(2) + ' A',
    amp: currentAmpVal,
    targetAmp: currentAmpVal,
    name: name,
    color: color,
    zoneId: chConf.zone,
    spot: chConf.spot,
    isOffline: false,
    activeCard: currentCard,
    activeUser: currentUser,
    last_update: new Date().toLocaleTimeString()
};

node.status({ fill: isCharging ? 'green' : (plugged ? 'yellow' : 'blue'), shape: 'dot', text: cid + ': ' + statusLabel + ' | ' + pKW + 'kW | ' + currentAmpVal + 'A | ' + singleE + 'kWh' });

msg.payload = resObj;
msg.chargerId = cid;
return msg;

msg.url = 'http://192.168.20.236/';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'optType=ReadSetData&pwd=SCQD8ADERF';
return msg;

let raw = msg.payload;
let arr = raw;
if (typeof raw === 'string') {
    try { arr = JSON.parse(raw); } catch(e) {}
}
if (!arr || !Array.isArray(arr) || arr.length < 80) {
    return null;
}

let cid = 'solax_1';
let appMaxAmp = Number(arr[76] || arr[2] || 0);

if (appMaxAmp >= 6 && appMaxAmp <= 32) {
