}

return null;

const token = "202408021703090259148812";
const sn = "SRR6N8ACRJ";
const timestamp = Date.now().toString();
const inputString = `${token}${timestamp}${sn}`;

const hash = crypto.createHash('sha256').update(inputString).digest('hex');

msg.token = token;
msg.sn = sn;
msg.timestamp = timestamp;
msg.inputString = inputString;
msg.payload = { Digest: hash };

return msg;

if (msg.payload && msg.payload.Digest) {
    const hash = msg.payload.Digest;
    msg.url = "https://www.solaxcloud.com:9443/proxy/api/getRealtimeInfo.do?tokenId=" + msg.token + "&sn=" + msg.sn + "&timestamp=" + msg.timestamp + "&hash=" + hash;
    msg.method = "GET";
} else {
    node.warn("SHA256 hash not received");
    return null;
}
return msg;

// Check if API returns success
if (msg.payload && msg.payload.success === true) {
    const data = msg.payload.result;

    // Extract core values
    msg.payload = {
        type: 'solax_update',
        inverterSN: data.inverterSN || 'Unknown',
        sn: data.sn || 'Unknown',
        acpower: data.acpower || 0,
        yieldtoday: data.yieldtoday || 0,
        yieldtotal: data.yieldtotal || 0,
        feedinpower: data.feedinpower || 0,
        uploadTime: data.uploadTime || 'Unknown',
        powerdc1: data.powerdc1 || 0,
        powerdc2: data.powerdc2 || 0,
        powerdc3: data.powerdc3 || 0
    };

    // Save to global context for UI retrieval
    global.set('lastSolaxData', msg.payload);

    // Log status
    node.log(`✅ AC Power: ${data.acpower}W, Today: ${data.yieldtoday}kWh, Total: ${data.yieldtotal}kWh`);

} else {
    // On error
    msg.payload = {
        error: msg.payload?.exception || 'Unknown error',
        success: false
    };
    node.warn(`❌ API Error: ${msg.payload.error}`);
}

return msg;

if (msg.topic === 'smart_config_request' ||
    msg.topic === 'cars_config_request' ||
    msg.topic === 'get_charging_history' ||
    msg.topic === 'reload_from_disk' ||
    msg.topic === 'restore_seed_config' ||
    msg.topic === 'factory_reset_config' ||
    (msg.payload && (msg.payload.type === 'smart_config' || msg.payload.type === 'cars_config'))) {
    return null;
}

const cid = msg.chargerId;
if (!cid || !msg.payload || typeof msg.payload !== 'object') {
